package com.agentguard.controller;
import com.agentguard.dto.PolicyResponse; import com.agentguard.service.PolicyService; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.math.BigDecimal; import java.time.Instant; import static org.mockito.ArgumentMatchers.any; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(PolicyController.class) class PolicyControllerTest { @Autowired MockMvc mvc; @MockBean PolicyService service; @Test void createsPolicy() throws Exception {Mockito.when(service.create(any())).thenReturn(new PolicyResponse(1L,1L,"software",new BigDecimal("100.00"),true,true,Instant.parse("2026-01-01T00:00:00Z")));mvc.perform(post("/api/policies").contentType(MediaType.APPLICATION_JSON).content("{\"userId\":1,\"category\":\"software\",\"maxAmount\":100.00,\"requiresApproval\":true,\"active\":true}")).andExpect(status().isCreated()).andExpect(jsonPath("$.category").value("software"));} }
